 * generated records, never overwrites user edits or existing hand-written entries.
 */
class EditorialNumberMeaningsSeeder extends Seeder {
    public function run(): void {
        $entries = [
            ['10', 'Первый шаг в неизвестность', 'Десятка соединяет импульс единицы с открытым пространством нуля. В нумерологической символике это не обещание удачи, а образ начала без полной карты. Желание заранее узнать исход часто маскируется под разумную подготовку, хотя на деле не даёт сдвинуться с места.', 'Возможность выбирать направление, не требуя гарантий.', 'Ожидание идеальной уверенности перед простым действием.', 'Какой первый шаг я откладываю лишь потому, что не вижу всю дорогу?', 'Назови действие на десять минут, которое можно совершить без больших обязательств.'],
            ['12', 'Остаться собой рядом с другим', 'Единица символизирует личную инициативу, двойка — встречу и сотрудничество. В числе 12 можно увидеть переход от «я решил» к «мы обсуждаем». Отношения не обязаны стирать различия: порой именно честно высказанная позиция делает близость глубже.', 'Умение слышать другого, не отказываясь от своего голоса.', 'Привычка соглашаться ради мира, а затем копить обиду.', 'Где я уступаю не из любви, а из страха разочаровать?', 'Сформулируй одно своё предпочтение спокойно и без оправданий.'],
            ['13', 'Разрешить себе быть услышанным', 'Единица говорит об индивидуальности, тройка — о выражении и творчестве. Тринадцать напоминает о расстоянии между внутренним ощущением и произнесёнными словами. Иногда мы молчим не потому, что нечего сказать, а потому, что боимся не понравиться.', 'Искренность, которой не нужна идеальная формулировка.', 'Желание выглядеть мудрым вместо готовности говорить честно.', 'Какую мысль я прячу за слишком правильными словами?', 'Напиши три предложения без редактирования и оценки.'],
            ['14', 'Свобода через устойчивость', 'В четырнадцати инициатива единицы встречается с дисциплиной четвёрки. Это образ человека, который понял: вдохновение открывает дверь, но пройти через неё помогают повторяемые действия. Порядок может быть не клеткой, а заботой о том, что тебе дорого.', 'Способность поддерживать важное без постоянного эмоционального подъёма.', 'Превращение полезных правил в суровый внутренний суд.', 'Какая привычка поддерживает мою свободу, а какая забирает её?', 'Выбери одно небольшое действие, которое реально повторять семь дней.'],
            ['15', 'Перемена или побег', 'Пятёрка символизирует движение, единица — личный выбор. В пятнадцати можно исследовать разницу между смелостью изменить жизнь и желанием немедленно перестать чувствовать неудобство. Новый адрес не всегда меняет старую реакцию.', 'Честность в выборе нового направления.', 'Постоянная смена обстоятельств вместо встречи с причиной беспокойства.', 'К чему я иду — или только от чего-то убегаю?', 'Запиши два ответа отдельно: «от чего» и «ради чего».'],
            ['16', 'Забота, в которой есть место себе', 'Шестёрку связывают с ответственностью и близкими, единицу — с собственной волей. Их соседство напоминает: помощь не должна превращаться в исчезновение себя. Быть нужным приятно, но это не единственное основание человеческой ценности.', 'Поддержка, сохраняющая границы и уважение.', 'Спасательство ради ощущения собственной незаменимости.', 'Кому я говорю «помогу», хотя сам уже истощён?', 'Перед следующим обещанием проверь свои силы и желание.'],
            ['17', 'Тишина после решения', 'Единица выбирает путь, семёрка обращается к внутреннему поиску. Семнадцать предлагает не путать самостоятельность с отказом от помощи, а размышление — с бесконечной проверкой решения. Иногда собственный ответ становится слышен только после паузы.', 'Внутренняя ясность без показной независимости.', 'Поиск всё новых советов, чтобы не отвечать за выбор.', 'Чьё одобрение я ищу, хотя уже знаю своё решение?', 'Запиши свою позицию до того, как спросишь чьё-либо мнение.'],
            ['18', 'Ценность больше результата', 'Восьмёрка ассоциируется с ресурсами и влиянием, единица — с личной инициативой. Восемнадцать может напомнить, как легко превратить достижения в единственное доказательство своей значимости. Но человек остаётся собой и в день, когда ничего не получилось.', 'Ответственность без жестокости к себе.', 'Измерение собственной ценности продуктивностью и статусом.', 'Кем я остаюсь, когда сегодня ничего не достиг?', 'Назови три качества, которые не измеряются деньгами и успехом.'],
            ['19', 'Закрыть дверь бережно', 'Девятка в нумерологической символике связана с завершением, единица — с началом. Девятнадцать показывает, что новое не всегда приходит после громкого разрыва: иногда достаточно признать, что прежний этап уже состоялся. Благодарность не требует оставаться в прошлом.', 'Способность завершать без обесценивания пережитого.', 'Привычка держаться за старую роль из чувства долга.', 'Какая история обо мне уже перестала быть правдой?', 'Закончи фразу: «Раньше я…, а сейчас учусь…».'],
            ['20', 'Пространство между словом и реакцией', 'Двойка — символ отношений, ноль — паузы и открытого пространства. Двадцать напоминает о коротком мгновении перед ответом: там можно заметить обиду, страх или желание доказать правоту. Не всякое чувство требует немедленного действия.', 'Умение выбирать ответ вместо автоматической реакции.', 'Молчание из страха конфликта, выдаваемое за спокойствие.', 'Когда моя пауза помогает понять, а когда скрывает правду?', 'В одном разговоре сделай вдох и назови про себя чувство перед ответом.'],
            ['21', 'Близость не отменяет личность', 'В двадцати одном символика отношений предшествует личному выбору. Иногда мы сначала привыкаем быть удобными, а затем с удивлением обнаруживаем, что не знаем собственных желаний. Честная близость выдерживает два разных голоса.', 'Сотрудничество, в котором сохраняется самостоятельность.', 'Согласие ради одобрения с последующим раздражением.', 'Где я называю компромиссом отказ от себя?', 'Выскажи одно небольшое предпочтение без чувства вины.'],
            ['23', 'Разговор как встреча', 'Двойка слушает, тройка выражает. Вместе они создают образ диалога, в котором важны и пауза, и собственный голос. Красноречие не заменяет интереса к человеку: можно произнести много красивых слов и так и не встретиться.', 'Любопытство к чужому опыту и ясность своего выражения.', 'Разговор, превращённый в выступление перед зрителем.', 'Что я хочу понять в собеседнике, а не доказать ему?', 'Задай открытый вопрос и не готовь ответ, пока слушаешь.'],
            ['24', 'Границы — тоже форма заботы', 'Двойка связывается с отношениями, четвёрка — со структурой. Двадцать четыре напоминает, что доверие растёт не только из тёплых чувств, но и из ясных договорённостей. Честное «сейчас не могу» иногда бережнее невыполнимого обещания.', 'Надёжность и уважение к собственным возможностям.', 'Жёсткие правила вместо разговора о потребностях.', 'Какое обещание я даю из страха расстроить другого?', 'Пересмотри одно обязательство и предложи реальный срок или объём.'],
            ['25', 'Двигаться, не разрывая связь', 'Двойка ищет близость, пятёрка — перемены. Их сочетание приглашает задуматься, почему свободу иногда принимают за одиночество, а верность — за неподвижность. Живые отношения способны меняться, если в них есть разговор.', 'Свобода, которая не требует исчезать из жизни близких.', 'Обвинение окружающих в ограничениях, о которых мы не говорили.', 'О какой перемене мне важно поговорить, прежде чем принимать решение?', 'Скажи: «Мне хотелось бы изменить…, потому что для меня важно…».'],
            ['26', 'Помогать, не присваивая чужую жизнь', 'Двойка говорит о контакте, шестёрка — о заботе. Двадцать шесть помогает заметить границу между поддержкой и управлением. Желание добра не даёт нам права прожить за другого его ошибки и открытия.', 'Забота, оставляющая другому право выбирать.', 'Обида, когда наши советы не выполняют.', 'Могу ли я уважать выбор близкого, даже если не согласен?', 'Прежде чем советовать, спроси, нужна ли помощь или просто присутствие.'],
            ['27', 'Не всякую тишину нужно объяснять', 'Двойка символизирует отношения, семёрка — внутренний мир. Двадцать семь напоминает, что чужое молчание не всегда связано с нами. Мы часто заполняем паузу догадками и начинаем отвечать на то, чего никто не говорил.', 'Терпение и уважение к внутреннему пространству другого.', 'Привычка считать любую дистанцию личным отвержением.', 'Какую историю я придумал о чужом молчании без доказательств?', 'Запиши три нейтральных объяснения ситуации, прежде чем делать вывод.'],
            ['28', 'Не отдавать свою ценность чужой оценке', 'Двойка ищет отклик, восьмёрка связана с результатом и признанием. В двадцати восьми можно увидеть соблазн оценивать себя глазами окружающих. Похвала приятна, но её отсутствие не делает труд бессмысленным.', 'Внутренняя мера качества и зрелое отношение к обратной связи.', 'Бесконечное сравнение себя с чужими достижениями.', 'Как я оценил бы свой труд, если бы его никто не заметил?', 'Запиши один результат, который важен тебе независимо от реакции.'],
            ['29', 'Отпускать ожидание, сохраняя уважение', 'Двойка символизирует связь, девятка — завершение. Двадцать девять не обязательно про расставание: иногда заканчивается лишь прежний способ ждать от человека того, чего он не может дать. Принятие не равно одобрению всего.', 'Умение менять форму отношений без мести и обесценивания.', 'Удерживание обиды как доказательства собственной правоты.', 'С каким ожиданием от другого мне трудно расстаться?', 'Отдельно запиши, что отношения дали, и чего они уже не дают.'],
            ['30', 'Слова, после которых можно помолчать', 'Тройка связывается с самовыражением, ноль — с паузой. Тридцать напоминает, что мысль не становится честнее от бесконечных объяснений. Иногда мы говорим слишком много, потому что боимся быть непонятыми.', 'Ясность, которой не нужно постоянно оправдываться.', 'Многословие как способ спрятать уязвимость.', 'Какую простую правду я усложняю, чтобы её легче приняли?', 'Сформулируй важную мысль одним предложением и остановись.'],
            ['31', 'Творчество начинается с решения', 'Тройка символизирует вдохновение, единица — первый самостоятельный шаг. Тридцать один — образ замысла, который перестаёт быть фантазией, когда получает пусть несовершенную форму. Черновик часто честнее бесконечной подготовки.', 'Смелость создавать, не требуя мгновенного мастерства.', 'Ожидание идеального настроения вместо практики.', 'Какую идею я защищаю от критики тем, что никогда не начинаю?', 'Десять минут поработай над намеренно несовершенным черновиком.'],
            ['32', 'Слышать ответ, которого не ожидал', 'Тройка говорит о выражении, двойка — о встрече. Тридцать два напоминает, что настоящий разговор способен изменить обе стороны. Если заранее решено, кто прав, слова другого становятся только фоном для собственного монолога.', 'Готовность пересматривать мнение без потери достоинства.', 'Использование откровенности как способа убедить собеседника.', 'Когда я в последний раз изменил мнение благодаря разговору?', 'Перескажи позицию другого и спроси, правильно ли ты её понял.'],
            ['34', 'Дать вдохновению место в расписании', 'Тройка связана с творчеством, четвёрка — с устойчивой формой. Тридцать четыре напоминает, что даже любимое дело нуждается в пространстве, времени и простых границах. Структура может не душить вдохновение, а защищать его от повседневной суеты.', 'Последовательное воплощение того, что действительно важно.', 'Бесконечное совершенствование системы вместо самого дела.', 'Какой маленькой опоры не хватает моей идее?', 'Забронируй пятнадцать минут для одного творческого действия.'],
            ['35', 'Иметь право передумать', 'Тройка выражает взгляд на мир, пятёрка приносит изменение. Тридцать пять предлагает вспомнить, что мнение — не клятва на всю жизнь. Мы можем узнать новое и перестать соглашаться с собой вчерашним, не становясь предателями собственного пути.', 'Гибкость и интеллектуальная честность.', 'Перемена взглядов лишь ради чужого одобрения.', 'Какое старое убеждение я защищаю по привычке?', 'Запиши одну мысль, которую опыт сделал сложнее и глубже.'],
            ['36', 'Мягкая правда', 'Тройка символизирует голос, шестёрка — заботу. Тридцать шесть напоминает, что желание не ранить другого иногда превращается в отказ от собственных чувств. Но мягкость не требует лжи, а честность не обязана быть грубой.', 'Способность говорить прямо и бережно одновременно.', 'Привычка скрывать недовольство, ожидая, что другой догадается.', 'Какую честную фразу я заменяю словами «всё нормально»?', 'Выскажи одно небольшое неудобство без обвинений.'],
            ['37', 'Знать и оставаться открытым', 'Тройка любит объяснять, семёрка — исследовать. Тридцать семь напоминает, что красивые ответы могут стать преградой для живого вопроса. Уверенность в собственной картине мира иногда мешает заметить то, что в неё не помещается.', 'Любознательность без необходимости немедленно всё назвать.', 'Превращение духовных или философских идей в повод считать себя выше других.', 'Где моё объяснение стало важнее непосредственного опыта?', 'Выбери привычное явление и пять минут наблюдай его без интерпретаций.'],
            ['38', 'Голос и влияние', 'Тройка символизирует выражение, восьмёрка — силу воздействия. Тридцать восемь предлагает исследовать, как слова меняют пространство вокруг нас. Влияние начинается не с числа слушателей, а с ответственности за сказанное.', 'Умение говорить так, чтобы помогать пониманию, а не управлять людьми.', 'Использование харизмы для получения одобрения или власти.', 'Что я хочу дать людям своим словом — и чего хочу получить от них?', 'Перед публикацией текста спроси себя, оставляет ли он читателю свободу думать.'],
            ['39', 'Завершить без последней речи', 'Тройка говорит о выражении, девятка — о завершении. Тридцать девять напоминает, что не каждую историю можно закрыть идеальным разговором. Иногда мы продолжаем объясняться, потому что надеемся наконец изменить прошлое.', 'Способность признать сказанное и несказанное, не застревая в них.', 'Попытка добиться окончательного признания своей правоты.', 'Какой разговор я мысленно повторяю, хотя он уже закончился?', 'Напиши письмо, которое не обязательно отправлять, и заверши его словами прощания.']
        ];
        $count = 0;
        foreach ($entries as $entry) {
            [$number, $title, $symbolism, $light, $shadow, $question, $practice] = $entry;
            $record = NumberMeaning::query()->where('number', $number)->first();
            if (!$record) { continue; }
            $text = (string) $record->symbolism;
            $generated = str_starts_with($text, 'Число ' . $number . ' можно использовать как повод для самонаблюдения.')
                || str_starts_with($text, 'Иногда мы замечаем число в тот момент')
                || str_starts_with($text, 'Представь это число не как указание судьбы')
                || str_starts_with($text, 'Не нужно верить, что совпадение что-то предсказывает')
                || str_starts_with($text, 'У чисел нет обязанности объяснять нашу жизнь')
                || str_starts_with($text, 'Смысл здесь рождается не в цифрах')
                || str_starts_with($text, 'Попробуй на мгновение оставить поиск тайного послания');
            if (!$generated) { continue; }
            $record->update([
                'title'=>$title, 'symbolism'=>$symbolism,
                'light_side'=>$light, 'shadow_side'=>$shadow,
                'reflection_question'=>$question, 'practice'=>$practice,
            ]);
            $count++;
        }
        $this->command?->info('Авторские записи обновлены: '.$count);
    }
}
